type official =
  | Secretary
  | Other_official of string  (* placeholder identity of the other US official referenced *)

(* delegate as defined by 7701(a)(12)(A): officer, employee, or agency
   duly authorized (directly or via one or more redelegations) to perform
   the function mentioned or described in context *)
type delegate = {
  delegate_entity : string;          (* officer, employee, or agency *)
  authorizing_official : official;   (* official whose authority is delegated *)
  duly_authorized : bool;            (* authorized directly or indirectly by redelegation *)
}

let is_secretary (ref_official : official) : bool =
  match ref_official with
  | Secretary -> true
  | Other_official _ -> false

(* (i): reference to Secretary of the Treasury *)
let meaning_of_delegate_secretary (ref_official : official) : delegate =
  { delegate_entity = "officer_employee_or_agency_of_treasury";
    authorizing_official = ref_official;
    duly_authorized = true }

(* (ii): reference to any other official of the United States, similarly construed *)
let meaning_of_delegate_other (ref_official : official) : delegate =
  { delegate_entity = "officer_employee_or_agency_of_official";
    authorizing_official = ref_official;
    duly_authorized = true }

(* (A): dispatch on whether reference is to Secretary or other official *)
let meaning_of_delegate (ref_official : official) : delegate =
  if is_secretary ref_official then meaning_of_delegate_secretary ref_official
  else meaning_of_delegate_other ref_official

type location =
  | Guam
  | American_samoa
  | Other_location of string

type tax_chapter =
  | Chapter_1
  | Chapter_2
  | Chapter_21
  | Other_chapter of int

(* context describing performance of functions in Guam/American Samoa for specific tax chapters *)
type performance_context = {
  location : location;
  chapter : tax_chapter;
}

let is_guam_or_american_samoa (loc : location) : bool =
  match loc with
  | Guam | American_samoa -> true
  | Other_location _ -> false

let is_covered_chapter (ch : tax_chapter) : bool =
  match ch with
  | Chapter_1 | Chapter_2 | Chapter_21 -> true
  | Other_chapter _ -> false

(* (B): delegate also includes officer/employee of any other US (or possession) department or agency, duly authorized by Secretary directly or via redelegation, for functions performed in Guam/American Samoa re chapters 1, 2, 21 *)
let meaning_of_delegate_guam_american_samoa (ctx : performance_context) : delegate =
  { delegate_entity = "officer_or_employee_of_other_department_agency_or_possession";
    authorizing_official = Secretary;
    duly_authorized = true }

(* 7701(a)(12): general meaning (A), expanded by (B) when function performed in Guam/American Samoa for chapters 1,2,21 *)
let meaning_of_delegate_7701_a_12 (ref_official : official) (ctx : performance_context option) : delegate =
  match ctx with
  | Some c when is_guam_or_american_samoa c.location && is_covered_chapter c.chapter ->
      meaning_of_delegate_guam_american_samoa c
  | _ -> meaning_of_delegate ref_official
